triggerer.SetMonsterBehaviour( NoAI );
ModifyState( minion_count, +1);
 this.skill_target = triggerer.GetLocation();
 this.effect_height = triggerer.GetHeight(); 
this.soul = PlayEffect("Metadata/Effects/Spells/monsters_effects/Act4_FOUR/KaruiSoulCaster/spawndeath.ao", height: effect_height ); soul.hostbody = this; soul.FaceObject( hostbody.skill_target);

